# ------------------------------------------------------------
# 2. FUNCIONES AUXILIARES
# ------------------------------------------------------------
def parse_fecha(fecha_str):
    if not isinstance(fecha_str, str):
        return None
    fecha_limpia = fecha_str.strip()
    if fecha_limpia in ("SIN CURSO", "NO APLICA", "RESTRICCIÓN", "", "00/01/1900"):
        return None
    try:
        return datetime.strptime(fecha_limpia, "%d/%m/%Y").date()
    except ValueError:
        return None

def crear_tablas(conn):
    cursor = conn.cursor()
    cursor.execute('''CREATE TABLE IF NOT EXISTS usuarios (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        rol TEXT NOT NULL,
        nombre_completo TEXT,
        activo BOOLEAN DEFAULT 1
    )''')
    cursor.execute('''CREATE TABLE IF NOT EXISTS empleados (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        cedula TEXT UNIQUE NOT NULL,
        nombre TEXT NOT NULL,
        usuario_id INTEGER,
        FOREIGN KEY(usuario_id) REFERENCES usuarios(id)
    )''')
    cursor.execute('''CREATE TABLE IF NOT EXISTS clientes (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nombre TEXT NOT NULL,
        codigo TEXT UNIQUE NOT NULL
    )''')
    cursor.execute('''CREATE TABLE IF NOT EXISTS cursos (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        nombre TEXT NOT NULL,
        cliente_id INTEGER NOT NULL,
        descripcion TEXT,
        duracion_horas INTEGER,
        vigencia_dias INTEGER DEFAULT 0,
        FOREIGN KEY(cliente_id) REFERENCES clientes(id)
    )''')
    cursor.execute('''CREATE TABLE IF NOT EXISTS asignaciones (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        empleado_id INTEGER NOT NULL,
        curso_id INTEGER NOT NULL,
        fecha_asignacion DATE NOT NULL,
        fecha_vencimiento DATE NOT NULL,
        estado TEXT DEFAULT 'pendiente',
        FOREIGN KEY(empleado_id) REFERENCES empleados(id),
        FOREIGN KEY(curso_id) REFERENCES cursos(id)
    )''')
    conn.commit()

def insertar_clientes(conn):
    cursor = conn.cursor()
    for nombre, codigo in clientes_data:
        cursor.execute("INSERT OR IGNORE INTO clientes (nombre, codigo) VALUES (?, ?)", (nombre, codigo))
    conn.commit()

def insertar_empleados_y_usuarios(conn):
    cursor = conn.cursor()
    for cedula, nombre in empleados_data:
        cursor.execute("SELECT id FROM empleados WHERE cedula = ?", (cedula,))
        if cursor.fetchone():
            continue
        cursor.execute("INSERT INTO empleados (cedula, nombre) VALUES (?, ?)", (cedula, nombre))
        emp_id = cursor.lastrowid
        hashed = generate_password_hash(cedula)
        cursor.execute('''INSERT INTO usuarios (username, password_hash, rol, nombre_completo, activo)
            VALUES (?, ?, 'empleado', ?, 1)''', (cedula, hashed, nombre))
        user_id = cursor.lastrowid
        cursor.execute("UPDATE empleados SET usuario_id = ? WHERE id = ?", (user_id, emp_id))
    conn.commit()

