def crear_todos_los_cursos(conn, reader):
    """
    Lee el CSV una vez y crea todos los cursos (nombre, cliente, vigencia)
    para que existan incluso si no tienen asignaciones válidas (ej. ECOEDUCATE).
    """
    import csv
    from io import StringIO
    cursor = conn.cursor()
    cursos_unicos = set()
    for row in reader:
        nombre_curso = row['CAPACITACIÓN'].strip()
        aplica_a = row['APLICA A'].strip()
        if aplica_a == "GENERAL":
                    aplica_a = "APC"
        vigencia_str = row['VIGENCIA (DÍAS)'].strip()
        try:
            vigencia = int(vigencia_str)
        except:
            vigencia = 0
        cursos_unicos.add((nombre_curso, aplica_a, vigencia))
    
    for nombre_curso, aplica_a, vigencia in cursos_unicos:
        # Buscar o crear el cliente
        cursor.execute("SELECT id FROM clientes WHERE nombre = ?", (aplica_a,))
        cliente = cursor.fetchone()
        if not cliente:
            codigo = ''.join(c for c in aplica_a.upper() if c.isalpha())[:10]
            cursor.execute("INSERT INTO clientes (nombre, codigo) VALUES (?, ?)", (aplica_a, codigo))
            cliente_id = cursor.lastrowid
        else:
            cliente_id = cliente[0]
        # Crear curso si no existe
        cursor.execute("SELECT id FROM cursos WHERE nombre = ? AND cliente_id = ?", (nombre_curso, cliente_id))
        if not cursor.fetchone():
            cursor.execute("INSERT INTO cursos (nombre, cliente_id, vigencia_dias) VALUES (?, ?, ?)",
                           (nombre_curso, cliente_id, vigencia))
    conn.commit()


def cargar_capacitaciones(conn):
    """Lee el string de texto y carga los cursos y asignaciones."""
    import csv
    from io import StringIO
    
    cursor = conn.cursor()
    reader = csv.DictReader(StringIO(capacitaciones_txt), delimiter=';')
    insertados = 0
    ignorados = 0
    
    for row in reader:
        cedula = row['CÉDULA'].strip()
        nombre_curso = row['CAPACITACIÓN'].strip()
        aplica_a = row['APLICA A'].strip()
        if aplica_a == "GENERAL":
            aplica_a = "APC"
        vigencia_dias = row['VIGENCIA (DÍAS)']
        fecha_real_str = row['FECHA REAL'].strip()
        estado = row['ESTADO'].strip().upper()
        
        # Buscar empleado
        cursor.execute("SELECT id FROM empleados WHERE cedula = ?", (cedula,))
        emp = cursor.fetchone()
        if not emp:
            ignorados += 1
            continue
        empleado_id = emp[0]
        
        # Ignorar NO APLICA, RESTRICCIÓN, SIN CURSO sin fecha
        if estado in ("NO APLICA", "RESTRICCIÓN") or (estado == "SIN CURSO" and fecha_real_str == ""):
            ignorados += 1
            continue
        
        fecha_real = parse_fecha(fecha_real_str)
        if fecha_real is None:
            ignorados += 1
            continue
        
        try:
            vigencia = int(vigencia_dias)
        except:
            ignorados += 1
            continue
        
        fecha_vencimiento = fecha_real + timedelta(days=vigencia)
        
        # Cliente
        cursor.execute("SELECT id FROM clientes WHERE nombre = ?", (aplica_a,))
        cliente = cursor.fetchone()
        if not cliente:
            # Crear cliente nuevo con código generado
            codigo = ''.join(c for c in aplica_a.upper() if c.isalpha())[:10]
            cursor.execute("INSERT INTO clientes (nombre, codigo) VALUES (?, ?)", (aplica_a, codigo))
            cliente_id = cursor.lastrowid
        else:
            cliente_id = cliente[0]
        
        # Obtener el curso (ya debe existir)
        cursor.execute("SELECT id, vigencia_dias FROM cursos WHERE nombre = ? AND cliente_id = ?", (nombre_curso, cliente_id))
        curso = cursor.fetchone()
        if not curso:
            # No debería ocurrir, pero por si acaso lo creamos (opcional)
            cursor.execute("INSERT INTO cursos (nombre, cliente_id, vigencia_dias) VALUES (?, ?, ?)",
                        (nombre_curso, cliente_id, vigencia))
            curso_id = cursor.lastrowid
            vigencia = vigencia
        else:
            curso_id, vigencia = curso
        
        # Estado asignación
        if estado == "VIGENTE":
            estado_asig = "completado"
        elif estado == "VENCIDO":
            estado_asig = "vencido"
        elif estado == "PROXIMO A VENCER":
            estado_asig = "pendiente"
        else:
            estado_asig = "pendiente"
        
        # Evitar duplicados
        cursor.execute('''SELECT id FROM asignaciones 
            WHERE empleado_id = ? AND curso_id = ? AND fecha_asignacion = ?''',
            (empleado_id, curso_id, fecha_real.isoformat()))
        if cursor.fetchone():
            ignorados += 1
            continue
        
        cursor.execute('''INSERT INTO asignaciones 
            (empleado_id, curso_id, fecha_asignacion, fecha_vencimiento, estado)
            VALUES (?, ?, ?, ?, ?)''',
            (empleado_id, curso_id, fecha_real.isoformat(), fecha_vencimiento.isoformat(), estado_asig))
        insertados += 1
        if insertados % 500 == 0:
            conn.commit()
            print(f"  Procesadas {insertados} asignaciones...")
    
    conn.commit()
    print(f"✅ Asignaciones insertadas: {insertados}")
    print(f"   Registros ignorados: {ignorados}")

